/// Get the last named child that is not `end`.
pub(crate) fn last_named_child_not_end(node: Node) -> Option<Node> {
    let mut result = None;
    let count = node.child_count();
    for i in 0..count {
        if let Some(child) = node.child(i) {
            if child.is_named() && child.kind() != "end" {
                result = Some(child);
            }
        }
    }
    result
}

